<script setup lang="ts">import { computed, ref } from 'vue';import { useSystemStore } from '../stores/system';import { api } from '../api/client';import Panel from '../components/Panel.vue';import StatusBadge from '../components/StatusBadge.vue';import EmptyState from '../components/EmptyState.vue';import { age } from '../format';const s=useSystemStore(),tab=ref<'entry'|'tp'|'manual'>('entry'),tps=computed(()=>s.snapshot?.tpOrders??[]),manual=ref<any[]>([]),ttl=(ts:number)=>Math.max(0,Math.ceil((ts-Date.now())/60000));async function loadManual(){try{manual.value=(await api.orders()).manual??[]}catch{manual.value=[]}}loadManual();</script>
<template><div class="page-stack"><div class="segmented"><button :class="{active:tab==='entry'}" @click="tab='entry'">建仓委托（{{s.snapshot?.account.activeEntryOrders??s.snapshot?.account.pendingEntries??0}}）</button><button :class="{active:tab==='tp'}" @click="tab='tp'">止盈委托（{{s.snapshot?.account.activeTpOrders??tps.length}}）</button><button :class="{active:tab==='manual'}" @click="tab='manual';loadManual()">人工委托（{{manual.filter(x=>['NEW','WORKING','PARTIALLY_FILLED'].includes(x.status)).length}}）</button></div><Panel v-if="tab==='entry'" title="建仓委托" subtitle="只显示 NEW / WORKING / PARTIALLY_FILLED；终态保留在审计和交易记录"><table class="data-table"><thead><tr><th>创建时间</th><th>Symbol</th><th>Direction</th><th>Qty</th><th>Maker Price</th><th>Filled</th><th>Age</th><th>TTL</th><th>状态</th><th>操作</th></tr></thead><tbody><tr v-for="o in s.snapshot?.entryOrders??[]" :key="o.id"><td>{{new Date(o.createdAt).toLocaleString()}}</td><td class="symbol">{{o.symbol}}</td><td>{{o.side}}</td><td>{{o.quantity}}</td><td>{{o.price}}</td><td>{{o.filledQuantity}}</td><td>{{age(o.createdAt)}}</td><td>{{ttl(o.absoluteExpiresAt)}}m</td><td><StatusBadge :value="o.status"/></td><td><button class="button tiny secondary" @click="s.cancelEntry(o.id)">取消</button></td></tr></tbody></table><EmptyState v-if="!s.snapshot?.entryOrders.length" title="当前没有活动建仓委托"/></Panel><Panel v-else-if="tab==='tp'" title="止盈委托" subtitle="只显示 WORKING TP；每个有效 Position 默认一套保护"><table class="data-table"><thead><tr><th>创建时间</th><th>Symbol</th><th>Position</th><th>Side</th><th>Qty</th><th>TP Price</th><th>Age</th><th>Coverage</th><th>操作</th></tr></thead><tbody><tr v-for="o in tps" :key="o.id"><td>{{new Date(o.createdAt).toLocaleString()}}</td><td class="symbol">{{o.symbol}}</td><td class="mono">{{o.positionId}}</td><td>{{o.side}}</td><td>{{o.quantity}}</td><td>{{o.price}}</td><td>{{age(o.createdAt)}}</td><td><StatusBadge value="PROTECTED"/></td><td><span class="muted">由持仓页管理</span></td></tr></tbody></table><EmptyState v-if="!tps.length" title="当前没有活动止盈委托"/></Panel><Panel v-else title="人工委托" subtitle="当前标的的手工减仓、同向加仓、限价与紧急操作均汇总于此"><table class="data-table"><thead><tr><th>创建时间</th><th>Symbol</th><th>Position</th><th>类型</th><th>方向</th><th>Qty</th><th>价格</th><th>reduceOnly / PostOnly</th><th>状态</th></tr></thead><tbody><tr v-for="o in manual" :key="o.id"><td>{{new Date(o.createdAt).toLocaleString()}}</td><td class="symbol">{{o.symbol}}</td><td class="mono">{{o.positionId}}</td><td>{{o.type}}</td><td>{{o.side}}</td><td>{{o.quantity}}</td><td>{{o.price??'市价'}}</td><td>{{o.reduceOnly?'YES':'NO'}} / {{o.postOnly?'YES':'NO'}}</td><td><StatusBadge :value="o.status"/></td></tr></tbody></table><EmptyState v-if="!manual.length" title="当前没有人工委托"/></Panel></div></template>
